            return false;
        }
        remaining[index]--;
        return true;
    }
}

class ParkingSystem {
    private int big;
    private int medium;
    private int small;

    public ParkingSystem(int big, int medium, int small) {
        this.big = big;
        this.medium = medium;
        this.small = small;
    }

    public boolean addCar(int carType) {
        if (carType == 1) {
            if (big == 0) return false;
            big--;
            return true;
        }
        if (carType == 2) {
            if (medium == 0) return false;
            medium--;
            return true;
        }
        if (small == 0) return false;
        small--;
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

class ParkingSystem {
    private final Map<Integer, Integer> remaining = new HashMap<>();

    public ParkingSystem(int big, int medium, int small) {
        remaining.put(1, big);
        remaining.put(2, medium);
        remaining.put(3, small);
    }

    public boolean addCar(int carType) {
        int slots = remaining.get(carType);
        if (slots == 0) {
            return false;
        }
        remaining.put(carType, slots - 1);
        return true;
    }
}

class ParkingSystem {
    private final int[] capacity;
    private final int[] occupied;

    public ParkingSystem(int big, int medium, int small) {
        capacity = new int[]{big, medium, small};
        occupied = new int[3];
    }

    public boolean addCar(int carType) {
        int index = carType - 1;
        if (occupied[index] == capacity[index]) {
            return false;
        }
        occupied[index]++;
        return true;
    }
}
